const { withDangerousMod, createRunOncePlugin } = require("expo/config-plugins");
const fs = require("fs");
const path = require("path");

/**
 * Xcode 27 rejects iOS deployment targets below 15.0. CocoaPods copies a
 * podspec's deployment target onto generated resource-bundle targets, while
 * React Native's post-install normalization only visits regular pod targets.
 * Keep every explicit Pods target aligned with the app's deployment target.
 */
const IOS_MARKER =
  "    # @generated by ./plugins/with-ios-deployment-targets\n";

const createPostInstallHook = (deploymentTarget) => `${IOS_MARKER}    ios_minimum_deployment_target = Gem::Version.new('${deploymentTarget}')
    installer.pods_project.targets.each do |pod_target|
      pod_target.build_configurations.each do |build_configuration|
        configured_deployment_target = build_configuration.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        next if configured_deployment_target.nil?

        if Gem::Version.new(configured_deployment_target) < ios_minimum_deployment_target
          build_configuration.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = ios_minimum_deployment_target.to_s
        end
      end
    end

`;

const insertAfterFirstMatch = (contents, pattern, insertion) => {
  const match = contents.match(pattern);
  if (!match || match.index === undefined) {
    return null;
  }
  const at = match.index + match[0].length;
  return `${contents.slice(0, at)}${insertion}${contents.slice(at)}`;
};

const withIosDeploymentTargets = (config) => {
  const deploymentTarget = config.ios?.deploymentTarget;
  if (!deploymentTarget) {
    throw new Error(
      "with-ios-deployment-targets requires expo.ios.deploymentTarget.",
    );
  }

  return withDangerousMod(config, [
    "ios",
    async (modConfig) => {
      const podfilePath = path.join(
        modConfig.modRequest.platformProjectRoot,
        "Podfile",
      );
      let contents = fs.readFileSync(podfilePath, "utf8");

      if (!contents.includes(IOS_MARKER.trim())) {
        const withHook = insertAfterFirstMatch(
          contents,
          /\n\s*post_install do \|installer\|\s*\n/,
          createPostInstallHook(deploymentTarget),
        );
        if (!withHook) {
          throw new Error(
            "with-ios-deployment-targets could not find the CocoaPods post_install block.",
          );
        }
        contents = withHook;
      }

      fs.writeFileSync(podfilePath, contents);
      return modConfig;
    },
  ]);
};

module.exports = createRunOncePlugin(
  withIosDeploymentTargets,
  "with-ios-deployment-targets",
  "1.0.0",
);
